// Python-compatible formatting primitives.
//
// Reimplements the exact text output of CPython's `repr(float)` and
// `repr(bytes)` so that encoded results match Python byte-for-byte.

/**
 * Format a JS number exactly like CPython's `repr(float)`.
 *
 * CPython produces the shortest decimal string that round-trips (same as
 * JS Number#toString), but applies its own layout rules: fixed notation
 * while the decimal point position is in (-4, 16], scientific notation
 * otherwise, and a mandatory ".0" suffix for integral floats.
 */
export function floatRepr(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
  if (value === 0) return Object.is(value, -0) ? '-0.0' : '0.0';

  const negative = value < 0;
  const text = Math.abs(value).toString();

  // Decompose the shortest representation into a digit string and a
  // decimal point position `decpt` such that:
  //     value = 0.<digits> * 10**decpt
  let digits;
  let decpt;
  const eIndex = text.indexOf('e');
  if (eIndex !== -1) {
    const mantissa = text.slice(0, eIndex);
    const exp10 = parseInt(text.slice(eIndex + 1), 10);
    digits = mantissa.replace('.', '');
    decpt = exp10 + 1;
  } else {
    const dot = text.indexOf('.');
    if (dot === -1) {
      digits = text.replace(/0+$/, '');
      decpt = text.length;
    } else if (text.slice(0, dot) !== '0') {
      digits = (text.slice(0, dot) + text.slice(dot + 1)).replace(/0+$/, '');
      decpt = dot;
    } else {
      const frac = text.slice(dot + 1);
      const leadingZeros = frac.match(/^0*/)[0].length;
      digits = frac.slice(leadingZeros).replace(/0+$/, '');
      decpt = -leadingZeros;
    }
  }

  let body;
  if (decpt <= -4 || decpt > 16) {
    // Scientific notation: d[.ddd]e±XX (exponent at least two digits).
    const exponent = decpt - 1;
    const mantissa =
      digits.length > 1 ? digits[0] + '.' + digits.slice(1) : digits;
    const sign = exponent < 0 ? '-' : '+';
    const expDigits = String(Math.abs(exponent)).padStart(2, '0');
    body = mantissa + 'e' + sign + expDigits;
  } else if (decpt <= 0) {
    body = '0.' + '0'.repeat(-decpt) + digits;
  } else if (decpt >= digits.length) {
    body = digits + '0'.repeat(decpt - digits.length) + '.0';
  } else {
    body = digits.slice(0, decpt) + '.' + digits.slice(decpt);
  }
  return negative ? '-' + body : body;
}

