// JSON string escaping compatible with CPython's json module when
// `ensure_ascii=False`: only `"`, `\` and control characters below 0x20
// are escaped; every other code point is emitted literally (it is later
// UTF-8 encoded when converted to bytes).

const NAMED_ESCAPES = new Map([
  [0x08, '\\b'],
  [0x09, '\\t'],
  [0x0a, '\\n'],
  [0x0c, '\\f'],
  [0x0d, '\\r'],
  [0x22, '\\"'],
  [0x5c, '\\\\'],
]);

/**
 * Encode a JS string as a JSON string literal (including the surrounding
 * quotes), matching Python's `json` encoder with ensure_ascii=False.
 */
export function encodeJsonString(text) {
  let out = '"';
  for (const ch of text) {
    const code = ch.codePointAt(0);
    if (code < 0x20 || code === 0x22 || code === 0x5c) {
      const named = NAMED_ESCAPES.get(code);
      out += named !== undefined
        ? named
        : '\\u' + code.toString(16).padStart(4, '0');
    } else {
      out += ch;
    }
  }
  return out + '"';
}

/**
 * Compare two strings by Unicode code point, like Python's `<` on `str`
 * (JS default string comparison uses UTF-16 code units, which orders
 * astral characters differently).
 */
export function compareCodePoints(a, b) {
  const aPoints = Array.from(a, (ch) => ch.codePointAt(0));
  const bPoints = Array.from(b, (ch) => ch.codePointAt(0));
  const length = Math.min(aPoints.length, bPoints.length);
  for (let i = 0; i < length; i++) {
    if (aPoints[i] !== bPoints[i]) return aPoints[i] - bPoints[i];
  }
  return aPoints.length - bPoints.length;
}

