// Canonical JSON encoder: a behavioral reimplementation of the Python
// `canonicaljson` package (which builds on CPython's `json` module with
// sort_keys=True, ensure_ascii=False and custom separators).
//
// Value model: plain JS objects are dicts (string keys), JS arrays are
// lists, JS strings are strings, BigInt values are integers and JS
// numbers are floats. booleans/null are also supported for completeness.

import { floatRepr } from './pyformat.mjs';
import { encodeJsonString, compareCodePoints } from './jsonescape.mjs';

/** Mirrors the ValueError raised by Python's json encoder with allow_nan=False. */
export class JsonEncodeError extends Error {}

function floatstr(value) {
  if (!Number.isFinite(value)) {
    throw new JsonEncodeError(
      `Out of range float values are not JSON compliant: ${floatRepr(value)}`,
    );
  }
  return floatRepr(value);
}

function isScalar(value) {
  const type = typeof value;
  return (
    value === null || type === 'string' || type === 'bigint' ||
    type === 'number' || type === 'boolean'
  );
}

function scalarstr(value) {
  const type = typeof value;
  if (type === 'string') return encodeJsonString(value);
  if (type === 'bigint') return value.toString();
  if (type === 'number') return floatstr(value);
  if (value === true) return 'true';
  if (value === false) return 'false';
  if (value === null) return 'null';
  throw new JsonEncodeError(`Object of type ${type} is not JSON serializable`);
}

// ---------------------------------------------------------------------------
// Iterative canonical encoding.
//
// Chunk boundaries reproduce CPython's pure-Python `_make_iterencode`:
// dicts yield '{', then per item an optional ',' separator, the encoded
// key, the ':' separator and the value (recursing for containers), then
// '}'. Lists keep a running buffer that starts as '[' and becomes ','
// after the first element, and yield that buffer *joined with* each
// scalar element as a single chunk.
// ---------------------------------------------------------------------------

function* iterencodeList(list) {
  if (list.length === 0) {
    yield '[]';
    return;
  }
  let buf = '[';
  for (const value of list) {
    if (isScalar(value)) {
      yield buf + scalarstr(value);
    } else {
      yield buf;
      yield* iterencodeContainer(value);
    }
    buf = ',';
  }
  yield ']';
}

function* iterencodeDict(dict) {
  const keys = Object.keys(dict);
  if (keys.length === 0) {
    yield '{}';
    return;
  }
  yield '{';
  keys.sort(compareCodePoints);
  let first = true;
  for (const key of keys) {
    if (first) {
      first = false;
    } else {
      yield ',';
    }
    yield encodeJsonString(key);
    yield ':';
    const value = dict[key];
    if (isScalar(value)) {
      yield scalarstr(value);
    } else {
      yield* iterencodeContainer(value);
    }
  }
  yield '}';
}

function* iterencodeContainer(value) {
  if (Array.isArray(value)) {
    yield* iterencodeList(value);
  } else {
    yield* iterencodeDict(value);
  }
}

/** Iteratively encode a value as canonical JSON, yielding string chunks. */
export function* iterencodeCanonicalJson(value) {
  if (isScalar(value)) {
    yield scalarstr(value);
  } else {
    yield* iterencodeContainer(value);
  }
}

/** Encode a value as the shortest canonical JSON string. */
export function encodeCanonicalJson(value) {
  let out = '';
  for (const chunk of iterencodeCanonicalJson(value)) {
    out += chunk;
  }
  return out;
}

// ---------------------------------------------------------------------------
// Pretty printed encoding: equivalent to Python's
// json.dumps(value, ensure_ascii=False, indent=4, sort_keys=True)
// ---------------------------------------------------------------------------

const INDENT = '    ';

export function encodePrettyPrintedJson(value, level = 0) {
  if (isScalar(value)) return scalarstr(value);

  const childIndent = INDENT.repeat(level + 1);
  const closingIndent = INDENT.repeat(level);

  if (Array.isArray(value)) {
    if (value.length === 0) return '[]';
    const items = value.map(
      (item) => childIndent + encodePrettyPrintedJson(item, level + 1),
    );
    return '[\n' + items.join(',\n') + '\n' + closingIndent + ']';
  }

  const keys = Object.keys(value);
  if (keys.length === 0) return '{}';
  keys.sort(compareCodePoints);
  const items = keys.map(
    (key) =>
      childIndent + encodeJsonString(key) + ': ' +
      encodePrettyPrintedJson(value[key], level + 1),
  );
  return '{\n' + items.join(',\n') + '\n' + closingIndent + '}';
}

