    yield scalarstr(value);
  } else {
    yield* iterencodeContainer(value);
  }
}

/** Encode a value as the shortest canonical JSON string. */
export function encodeCanonicalJson(value) {
  let out = '';
  for (const chunk of iterencodeCanonicalJson(value)) {
    out += chunk;
  }
  return out;
}

// ---------------------------------------------------------------------------
// Pretty printed encoding: equivalent to Python's
// json.dumps(value, ensure_ascii=False, indent=4, sort_keys=True)
// ---------------------------------------------------------------------------

const INDENT = '    ';

export function encodePrettyPrintedJson(value, level = 0) {
  if (isScalar(value)) return scalarstr(value);

  const childIndent = INDENT.repeat(level + 1);
  const closingIndent = INDENT.repeat(level);

  if (Array.isArray(value)) {
    if (value.length === 0) return '[]';
    const items = value.map(
      (item) => childIndent + encodePrettyPrintedJson(item, level + 1),
    );
    return '[\n' + items.join(',\n') + '\n' + closingIndent + ']';
  }

  const keys = Object.keys(value);
  if (keys.length === 0) return '{}';
  keys.sort(compareCodePoints);
  const items = keys.map(
    (key) =>
      childIndent + encodeJsonString(key) + ': ' +
      encodePrettyPrintedJson(value[key], level + 1),
  );
  return '{\n' + items.join(',\n') + '\n' + closingIndent + '}';
}

