// Minimal argparse-compatible command line parser.
//
// Reproduces the behavior of Python's argparse for a parser consisting
// only of required optional arguments with types str/int/float: same
// usage/error text, same exit codes (0 for --help, 2 for parse errors),
// '--opt value' and '--opt=value' forms, unique-prefix abbreviation,
// negative-number values, and Python's int()/float() literal rules.

import { strRepr } from './pyformat.mjs';

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;
const INT_LITERAL = /^[+-]?\d(?:_?\d)*$/;
const FLOAT_LITERAL = new RegExp(
  '^[+-]?(?:' +
    '(?:(?:\\d(?:_?\\d)*)?\\.(?:\\d(?:_?\\d)*)|(?:\\d(?:_?\\d)*)\\.?)' +
    '(?:[eE][+-]?\\d(?:_?\\d)*)?' +
    '|inf(?:inity)?|nan' +
  ')$',
  'i',
);

function progName() {
  const script = process.argv[1];
  return script ? script.split(/[\\/]/).pop() : 'test10.mjs';
}

export class ArgumentParser {
  constructor() {
    this.prog = progName();
    this.optionals = [];
  }

  addArgument(flag, { type = 'str', required = false } = {}) {
    const dest = flag.replace(/^--?/, '');
    this.optionals.push({
      flag,
      dest,
      type,
      required,
      metavar: dest.toUpperCase(),
    });
  }

  formatUsage() {
    const parts = this.optionals.map((opt) => `${opt.flag} ${opt.metavar}`);
    return `usage: ${this.prog} [-h] ${parts.join(' ')}`;
  }

  formatHelp() {
    const lines = [
      this.formatUsage(),
      '',
      'options:',
      '  -h, --help  show this help message and exit',
      ...this.optionals.map((opt) => `  ${opt.flag} ${opt.metavar}`),
    ];
    return lines.join('\n') + '\n';
  }

  printHelpAndExit() {
    process.stdout.write(this.formatHelp());
    process.exit(0);
  }

  error(message) {
    process.stderr.write(this.formatUsage() + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  looksLikeNegativeNumber(token) {
    return NEGATIVE_NUMBER.test(token);
  }

  looksLikeOption(token) {
    if (!token.startsWith('-') || token === '-') return false;
    if (this.looksLikeNegativeNumber(token)) return false;
    if (token.includes(' ')) return false;
    return true;
  }

  convert(spec, raw) {
    const trimmed = raw.trim();
    if (spec.type === 'int') {
      if (!INT_LITERAL.test(trimmed)) {
        this.error(`argument ${spec.flag}: invalid int value: ${strRepr(raw)}`);
      }
      return BigInt(trimmed.replace(/_/g, ''));
    }
    if (spec.type === 'float') {
      if (!FLOAT_LITERAL.test(trimmed)) {
        this.error(`argument ${spec.flag}: invalid float value: ${strRepr(raw)}`);
      }
      const cleaned = trimmed.replace(/_/g, '');
      const lower = cleaned.toLowerCase();
      const body = lower.replace(/^[+-]/, '');
      if (body === 'inf' || body === 'infinity') {
        return lower.startsWith('-') ? -Infinity : Infinity;
      }
      if (body === 'nan') return NaN;
      return Number(cleaned);
    }
    return raw;
  }

  parseArgs(argv) {
    const longFlags = ['--help', ...this.optionals.map((opt) => opt.flag)];
    const values = {};
    const extras = [];
    let afterDoubleDash = false;
    let i = 0;

    while (i < argv.length) {
      const token = argv[i];

      if (afterDoubleDash) {
        extras.push(token);
        i += 1;
        continue;
      }
      if (token === '--') {
        afterDoubleDash = true;
        i += 1;
        continue;
      }
      if (token === '-h') {
        this.printHelpAndExit();
      }

      if (token.startsWith('--') && token.length > 2) {
        const eq = token.indexOf('=');
        const name = eq === -1 ? token : token.slice(0, eq);
        const inlineValue = eq === -1 ? null : token.slice(eq + 1);

        let matched = longFlags.includes(name) ? name : null;
        if (matched === null) {
          const candidates = longFlags.filter((flag) => flag.startsWith(name));
          if (candidates.length === 1) {
            matched = candidates[0];
          } else if (candidates.length > 1) {
            this.error(
              `ambiguous option: ${name} could match ${candidates.join(', ')}`,
            );
          }
        }
        if (matched === null) {
          extras.push(token);
          i += 1;
          continue;
        }
        if (matched === '--help') {
          this.printHelpAndExit();
        }

        const spec = this.optionals.find((opt) => opt.flag === matched);
        let raw;
        if (inlineValue !== null) {
          raw = inlineValue;
        } else {
          const next = argv[i + 1];
          if (next === undefined || this.looksLikeOption(next)) {
            this.error(`argument ${spec.flag}: expected one argument`);
          }
          raw = next;
          i += 1;
        }
        values[spec.dest] = this.convert(spec, raw);
        i += 1;
        continue;
      }

      // Unknown short option or a positional: no positionals are defined,
      // so anything here is unrecognized.
      extras.push(token);
      i += 1;
    }

    const missing = this.optionals
      .filter((opt) => opt.required && !(opt.dest in values))
      .map((opt) => opt.flag);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return values;
  }
}

