// Node.js (ESM) port of /workspace/dataset/canonicaljson/test10.py.
//
// Mirrors the Python script: parse --a (str), --b (int), --c (float),
// build the same dict, and print the canonical JSON bytes repr, the
// pretty printed JSON bytes repr, and the iterative chunk count.

import { ArgumentParser } from './lib/argparse.mjs';
import {
  encodeCanonicalJson,
  encodePrettyPrintedJson,
  iterencodeCanonicalJson,
  JsonEncodeError,
} from './lib/encoder.mjs';
import { bytesRepr } from './lib/pyformat.mjs';

function main() {
  const parser = new ArgumentParser();
  parser.addArgument('--a', { type: 'str', required: true });
  parser.addArgument('--b', { type: 'int', required: true });
  parser.addArgument('--c', { type: 'float', required: true });
  const args = parser.parseArgs(process.argv.slice(2));

  const data = {
    string: args.a,
    integer: args.b,
    float: args.c,
    list: [args.a, args.b, args.c],
  };

  try {
    const canonicalResult = encodeCanonicalJson(data); // Encode as canonical JSON
    const prettyResult = encodePrettyPrintedJson(data); // Encode as pretty printed JSON
    const canonicalChunks = [...iterencodeCanonicalJson(data)]; // Get chunks from iterative encoding
    console.log(bytesRepr(canonicalResult));
    console.log(bytesRepr(prettyResult));
    console.log(canonicalChunks.length);
  } catch (err) {
    if (err instanceof JsonEncodeError) {
      // Python raises: ValueError: Out of range float values are not JSON compliant: <value>
      process.stderr.write(`ValueError: ${err.message}\n`);
      process.exit(1);
    }
    throw err;
  }
}

main();

